import { test, expect } from '@playwright/test';

test.describe('Login Loading Spinner', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/login');
  });

  test('should display loading spinner while login request is processing', async ({ page }) => {
    // Setup intercept for login API
    await page.route('**/api/auth/login', (route) => {
      route.abort('Request aborted');
    });

    // Verify spinner is visible initially
    const spinner = page.getByRole('status');
    await expect(spinner).toBeVisible();

    // Verify spinner has correct text
    await expect(spinner).toContainText('Loading...');

    // Verify login button is enabled
    const loginButton = page.getByRole('button', { name: /sign in/i });
    await expect(loginButton).toBeEnabled();

    // Fill login form
    const emailInput = page.getByLabel(/email/i);
    await emailInput.fill('user@example.com');

    const passwordInput = page.getByLabel(/password/i);
    await passwordInput.fill('password123');

    // Click login button
    await loginButton.click();

    // Wait for spinner to disappear
    const spinnerAfterClick = page.getByRole('status');
    await expect(spinnerAfterClick).not.toBeVisible();

    // Verify login success message appears
    const successMessage = page.getByText(/logged in/i);
    await expect(successMessage).toBeVisible();

    // Verify user is redirected to dashboard
    const dashboard = page.getByRole('region', { name: /dashboard/i });
    await expect(dashboard).toBeVisible();
  });

  test('should hide spinner and show error message when login fails', async ({ page }) => {
    // Setup intercept for failed login API
    await page.route('**/api/auth/login', (route) => {
      route.abort('Failed to authenticate');
    });

    // Verify spinner is visible initially
    const spinner = page.getByRole('status');
    await expect(spinner).toBeVisible();

    // Verify spinner has correct text
    await expect(spinner).toContainText('Loading...');

    // Fill login form
    const emailInput = page.getByLabel(/email/i);
    await emailInput.fill('user@example.com');

    const passwordInput = page.getByLabel(/password/i);
    await passwordInput.fill('wrongpassword');

    // Click login button
    const loginButton = page.getByRole('button', { name: /sign in/i });
    await loginButton.click();

    // Wait for spinner to disappear
    const spinnerAfterClick = page.getByRole('status');
    await expect(spinnerAfterClick).not.toBeVisible();

    // Verify error message appears
    const errorMessage = page.getByText(/authentication failed/i);
    await expect(errorMessage).toBeVisible();

    // Verify login button is disabled
    await expect(loginButton).not.toBeEnabled();

    // Verify user is not redirected
    const dashboard = page.getByRole('region', { name: /dashboard/i });
    await expect(dashboard).not.toBeVisible();
  });
});
